import {RecipeDemo,DEMO_MATERIALS,PREPARATIONS,DEMO_GUNS} from './recipe-demo-model.mjs';
import {drawProjectile} from './projectile-effects.mjs';
const $=id=>document.getElementById(id),model=new RecipeDemo();let route='hydrogen';
const stock=values=>Object.entries(values).map(([id,n])=>`${DEMO_MATERIALS[id].formula} ×${n}`).join(' + ');
function render(message=''){
 $('inventory').innerHTML=Object.entries(DEMO_MATERIALS).map(([id,m])=>`<div class="material ${model.inventory[id]===0?'empty':''}" style="--color:${m.color}"><span class="material-symbol" style="${m.formula.length>6?'font-size:10px':''}">${m.formula}</span><span class="material-copy"><b>${m.name}</b><small>${id==='ferrous_chloride'?'副产物 · 保留记录':id==='hydrogen'||id==='carbon_dioxide'?'可制备的中间物质':'起始原料'}</small></span><strong class="material-count">${model.inventory[id]}</strong></div>`).join('');
 $('preparations').innerHTML=Object.entries(PREPARATIONS).map(([id,r])=>{const missing=model.missing(r.cost),ready=!Object.keys(missing).length,needsIgnition=id==='carbon_dioxide'&&!model.ignition;return `<article class="reaction ${route==='hydrogen'&&id==='hydrogen'&&model.inventory.hydrogen===0&&!model.guns.includes('flame')?'highlight':''}"><div class="reaction-title"><h3>${r.name}</h3><span>物质制备</span></div><div class="formula">${r.equation}</div><div class="condition">反应条件：${r.condition}</div><p>${r.fact}</p><div class="recipe-cost">消耗 ${stock(r.cost)}<br>获得 ${stock(r.products)}</div><button data-prepare="${id}" ${!ready||needsIgnition?'disabled':''}>${r.name}<span>→</span></button><div class="missing">${!ready?'还缺 '+stock(missing):needsIgnition?'需要打开测试炉点火源':'材料足够，点击即可反应'}</div></article>`}).join('');
 $('guns').innerHTML=Object.entries(DEMO_GUNS).map(([id,r])=>{const owned=model.guns.includes(id),missing=model.missing(r.cost),ready=!Object.keys(missing).length;return `<article class="gun ${route==='iron'&&id==='iron'&&!owned||route==='hydrogen'&&id==='flame'&&model.inventory.hydrogen>0&&!owned?'highlight':''}" style="--color:${r.color}"><div class="gun-title"><h3>${r.name}</h3><span>${owned?'已装配':'装备制造'}</span></div><p>${r.summary}</p><div class="recipe-cost">消耗 ${stock(r.cost)}</div><button ${owned?`data-select="${id}" class="preview-button"`:`data-assemble="${id}"`} ${!owned&&!ready?'disabled':''}>${owned?model.selected===id?'正在预览':'预览这把枪':'装配'+r.name}<span>${owned?'✓':'↗'}</span></button><div class="missing">${owned?'装备已完成，重复预览不消耗材料':!ready?'还缺 '+stock(missing):'配方就绪'}</div><p>${r.note}</p></article>`}).join('');
 $('ignition').checked=model.ignition;
 const last=model.history.at(-1);$('guide').textContent=message||(route==='iron'?'直接点击右侧“装配铁弹枪”，观察中间制氢路线的材料是否还够。':'先点击“制备氢气”，再用新得到的 H₂ 装配氢燃烧枪。');
 $('comparison').textContent=model.guns.includes('iron')?'两份铁都用于铁弹枪，背包中的铁已经为 0。虽然盐酸还在，制氢路线也因缺铁而暂时不可用。':model.guns.includes('flame')?`你用铁制氢，再用氢气装配了火焰枪。还剩 Fe ×${model.inventory.iron}，铁弹枪需要 Fe ×2：同一批资源已经走出了不同结果。`:model.history.some(e=>e.id==='hydrogen')?`你把铁用于制氢，现在背包有 H₂ ×${model.inventory.hydrogen}，还记录了 FeCl₂ ×${model.inventory.ferrous_chloride}。这不是只扣材料换枪：你先改变了手里的可用物质。`:'起始有 Fe ×2：可以直接装铁弹枪；也能消耗其中一份铁制氢，再走火焰枪路线。';
 $('history').innerHTML=model.history.length?[...model.history].reverse().map((e,i)=>`<div class="history-row"><span>${String(model.history.length-i).padStart(2,'0')} · ${e.kind==='prepare'?'制备':'装配'}：${e.name}</span><span><span class="negative">− ${stock(e.cost)}</span> <span class="positive">→ ${e.kind==='prepare'?stock(e.products):'获得 '+e.name}</span></span></div>`).join(''):'<div class="history-empty">还没有操作。原料、产物和装备将分别记录。</div>';
 $('previewName').textContent=model.selected?'当前装配：'+DEMO_GUNS[model.selected].name:'装配后可预览枪型';
}
function execute(kind,id){const result=kind==='prepare'?model.prepare(id):model.assemble(id);if(!result.ok){render('当前条件不足，请查看配方卡下方的缺料提示。');return}const e=result.event;render(kind==='prepare'?`消耗 ${stock(e.cost)}，获得 ${stock(e.products)}。${id==='hydrogen'?'现在可以装配氢燃烧枪了。':'现在可以装配气压枪了。'}`:`${e.name}已装配。观察剩余库存，再试试还能走哪些路线。`)}
$('preparations').addEventListener('click',e=>{const button=e.target.closest('[data-prepare]');if(button)execute('prepare',button.dataset.prepare)});
$('guns').addEventListener('click',e=>{const craft=e.target.closest('[data-assemble]'),preview=e.target.closest('[data-select]');if(craft)execute('assemble',craft.dataset.assemble);else if(preview&&model.select(preview.dataset.select))render('正在预览'+DEMO_GUNS[model.selected].name+'，预览不会再次扣材料。')});
$('ignition').onchange=()=>{model.ignition=$('ignition').checked;render('点火源'+(model.ignition?'已开启。':'已关闭；铁与稀盐酸这条路线不需要点火，碳燃烧需要。'))};
$('reset').onclick=()=>{model.reset();render('库存已重置。可以用相同的起始材料试另一条路线。')};
$('routeHydrogen').onclick=()=>{model.reset();route='hydrogen';render()};$('routeIron').onclick=()=>{model.reset();route='iron';render()};
const canvas=$('preview'),c=canvas.getContext('2d');
function frame(now){const rect=canvas.getBoundingClientRect(),scale=Math.min(devicePixelRatio||1,2),w=rect.width,h=rect.height;if(canvas.width!==Math.round(w*scale)||canvas.height!==Math.round(h*scale)){canvas.width=Math.round(w*scale);canvas.height=Math.round(h*scale)}c.setTransform(scale,0,0,scale,0,0);c.clearRect(0,0,w,h);const time=now/1000;
 c.strokeStyle='#567b4a22';c.lineWidth=1;for(let x=0;x<w;x+=28){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke()}c.fillStyle='#65816c';c.fillRect(22,h/2-10,30,17);c.fillStyle=model.selected?DEMO_GUNS[model.selected].color:'#7a9175';c.fillRect(30,h/2-8,33,7);c.fillRect(30,h/2+5,8,14);
 if(model.selected){c.save();c.beginPath();c.rect(60,0,w-60,h);c.clip();const length=Math.min(150,w-75);if(model.selected==='iron'){const x=63+(time*270)%length;drawProjectile(c,{type:'iron',x,y:h/2-4,originX:63,originY:h/2-4,vx:900,vy:0,life:1},time)}else drawProjectile(c,{type:model.selected,visual:'cone',x:62,y:h/2-4,originX:62,originY:h/2-4,angle:0,length,halfAngle:.35,life:.4,duration:.4},time);c.restore()}else{c.font='10px sans-serif';c.fillStyle='#6c8d70';c.textAlign='center';c.fillText('装配后，这里会展示枪型效果',w*.6,h/2)}requestAnimationFrame(frame)
}
render();requestAnimationFrame(frame);
